// Remplacer les placeholders par les vraies valeurs
const response = $input.item.json.output || $input.item.json.text || $input.item.json.response;
const invite1 = $('Parse Input Code').item.json.invite1;
const voiceId1 = $('Parse Input Code').item.json.voiceId1;
const invite2 = $('Parse Input Code').item.json.invite2;
const voiceId2 = $('Parse Input Code').item.json.voiceId2;

// Remplacer les placeholders
let processed = response
  .replace(/NOM_INVITE_1/g, invite1)
  .replace(/VOICE_ID_1/g, voiceId1)
  .replace(/NOM_INVITE_2/g, invite2)
  .replace(/VOICE_ID_2/g, voiceId2);

return { response: processed };

// Parser le message utilisateur pour extraire les informations
const messageText = $input.item.json.parsedData;

const lines = messageText.split('\n').map(l => l.trim());

let sujet = '';
let invite1 = '';
let voiceId1 = '';
let invite2 = '';
let voiceId2 = '';

for (const line of lines) {
  if (line.toLowerCase().startsWith('sujet:')) {
    sujet = line.substring(line.indexOf(':') + 1).trim();
  } else if (line.toLowerCase().startsWith('invité 1:') || line.toLowerCase().startsWith('invite 1:')) {
    invite1 = line.substring(line.indexOf(':') + 1).trim();
  } else if (line.toLowerCase().startsWith('voice id 1:') || line.toLowerCase().startsWith('voiceid 1:')) {
    voiceId1 = line.substring(line.indexOf(':') + 1).trim();
  } else if (line.toLowerCase().startsWith('invité 2:') || line.toLowerCase().startsWith('invite 2:')) {
    invite2 = line.substring(line.indexOf(':') + 1).trim();
  } else if (line.toLowerCase().startsWith('voice id 2:') || line.toLowerCase().startsWith('voiceid 2:')) {
    voiceId2 = line.substring(line.indexOf(':') + 1).trim();
  }
}

return {
  sujet,
  invite1,
  voiceId1,
  invite2,
  voiceId2,
  chatId: $input.item.json.chatId
};

