// Extraire et parser la réponse JSON de Claude
const response = $input.item.json.response;

let dialogueArray;

try {
  // Nettoyer la réponse si elle contient des markdown
  let cleaned = response.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  // Tenter de réparer le JSON si incomplet
  // Vérifier si le JSON est tronqué (ne se termine pas par ])
  if (!cleaned.endsWith(']')) {
    console.log('JSON incomplet détecté, tentative de réparation...');

    // Trouver la dernière entrée complète
    const lastCompleteObject = cleaned.lastIndexOf('},');
    if (lastCompleteObject > -1) {
      // Couper après la dernière entrée complète et fermer le tableau
      cleaned = cleaned.substring(0, lastCompleteObject + 1) + '\n]';
      console.log('JSON réparé: entrées incomplètes supprimées');
    } else {
      // Essayer de fermer l'objet et le tableau en cours
      if (cleaned.includes('{') && !cleaned.endsWith('}')) {
        cleaned = cleaned + '"\n  }\n]';
      } else {
        cleaned = cleaned + '\n]';
      }
    }
  }

  // Parser le JSON
  dialogueArray = JSON.parse(cleaned);

  // Vérifier que c'est bien un tableau
  if (!Array.isArray(dialogueArray)) {
    throw new Error('La réponse n\'est pas un tableau');
  }

  // Filtrer les entrées invalides (sans speaker, voiceId ou input)
  dialogueArray = dialogueArray.filter(item => 
    item.speaker && item.voiceId && item.input && item.input.length > 10
  );

  // Vérifier le nombre de lignes
  const count = dialogueArray.length;
  console.log(`${count} lignes valides générées`);

  if (count < 20) {
    throw new Error(`Trop peu de lignes générées: ${count} (minimum 20 requis)`);
  }

  if (count < 30) {
    console.log(`Attention: ${count} lignes générées (attendu: 30-32)`);
  }

  return dialogueArray;

} catch (error) {
  const preview = response.substring(0, 800);
  throw new Error(`Erreur de parsing JSON: ${error.message}\n\nRéponse reçue (début):\n${preview}\n\n[...réponse tronquée]`);
}

